        return 0 <= x < w and 0 <= y < h

    def adj8(a, b):
        return max(abs(a[0] - b[0]), abs(a[1] - b[1])) == 1

    if opp_t:
        best_t = None
        best_v = -10**18
        candidates = list(opp_t)
    else:
        best_t = None
        best_v = -10**18
