        near_self = 1 if any(adj8((tx, ty), s) for s in self_t) else 0
        near_opp = 1 if any(adj8((tx, ty), o) for o in opp_t) else 0
        if (tx, ty) in opp_t:
            v = 140.0 - 0.25 * d_our + 5.0 * near_self + 2.0 * near_opp
        else:
