        if v > best_v:
            best_v = v
            best_t = (tx, ty)

    tx, ty = best_t if best_t is not None else (sx, sy)
    best_moves = []
    for dx, dy in dirs:
        nx, ny = sx + dx, sy + dy
        if not inb(nx, ny) or (nx, ny) in obstacles:
            continue
        man = abs(tx - nx) + abs(ty - ny)
        capture_bonus = 0.0
        if (nx, ny) in opp_t:
