        elif (nx, ny) in unclaimed:
            capture_bonus = 12.0
        elif (nx, ny) in self_t:
            capture_bonus = 2.0
        best_moves.append((man - capture_bonus, dx, dy))
    best_moves.sort()
    if best_moves:
        return [int(best_moves[0][1]), int(best_moves[0][2])]
