    h = int(observation["grid_height"])
    sx, sy = observation["self_position"]
    ox, oy = observation["opponent_position"]

    obstacles = set()
    for p in (observation.get("obstacles") or []):
        if p and len(p) >= 2:
            x, y = p[0], p[1]
            if 0 <= x < w and 0 <= y < h:
                obstacles.add((x, y))

    unclaimed = []
    for p in (observation.get("unclaimed_cells") or []):
        if p and len(p) >= 2:
            x, y = p[0], p[1]
            if 0 <= x < w and 0 <= y < h and (x, y) not in obstacles:
                unclaimed.append((x, y))

    opp_set = set()
    for p in (observation.get("opponent_territory") or []):
        if p and len(p) >= 2:
            x, y = p[0], p[1]
            if 0 <= x < w and 0 <= y < h and (x, y) not in obstacles:
                opp_set.add((x, y))

    def neighbors8(x, y):
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if 0 <= nx < w and 0 <= ny < h:
                    yield nx, ny

    def edge_bias(x, y):
        return (1 if x in (0, w - 1) else 0) + (1 if y in (0, h - 1) else 0)

    def adj_opp(x, y):
        c = 0
        for nx, ny in neighbors8(x, y):
            if (nx, ny) in opp_set:
                c += 1
        return c

    # Choose a target deterministically: adjacent-to-opponent unclaimed first, else any unclaimed, else stay.
    target = None
    best = None
    if unclaimed:
        for x, y in unclaimed:
            a = adj_opp(x, y)
            # Prefer edge cells, then frontier (adjacent to opp), but also avoid going too close to opponent center.
            # Deterministic tie-break via coordinate ordering.
            dist_to_opp = abs(x - ox) + abs(y - oy)
